import{_ as t,o as s,c as a,a3 as n}from"./chunks/framework.BlfGB29P.js";const k=JSON.parse('{"title":"Tenant API v1 — Inventory","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Inventory | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-inventory"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Inventory | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-inventory"}]]},"headers":[],"relativePath":"api/tenant-v1-inventory.md","filePath":"api/tenant-v1-inventory.md","lastUpdated":1786892586000}'),i={name:"api/tenant-v1-inventory.md"};function o(r,e,d,c,l,h){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="tenant-api-v1-—-inventory" tabindex="-1">Tenant API v1 — Inventory <a class="header-anchor" href="#tenant-api-v1-—-inventory" aria-label="Permalink to &quot;Tenant API v1 — Inventory&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code>. Routes require authenticated, verified tenant access, <code>module:inventory</code>, and the applicable <code>inventory.*</code> permission. Inventory requires Products.</p><h2 id="stock" tabindex="-1">Stock <a class="header-anchor" href="#stock" aria-label="Permalink to &quot;Stock&quot;">​</a></h2><h3 id="get-inventory-stock" tabindex="-1">GET <code>/inventory/stock</code> <a class="header-anchor" href="#get-inventory-stock" aria-label="Permalink to &quot;GET `/inventory/stock`&quot;">​</a></h3><p>Query: <code>product_id</code>, <code>warehouse_id</code>, <code>search</code> (SKU/name), <code>low_stock</code>, <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><h3 id="get-inventory-stock-stats" tabindex="-1">GET <code>/inventory/stock/stats</code> <a class="header-anchor" href="#get-inventory-stock-stats" aria-label="Permalink to &quot;GET `/inventory/stock/stats`&quot;">​</a></h3><p>Returns <code>total_skus_with_stock</code>, <code>low_stock_count</code>, and <code>total_on_hand</code>.</p><h3 id="get-inventory-stock-movements" tabindex="-1">GET <code>/inventory/stock/movements</code> <a class="header-anchor" href="#get-inventory-stock-movements" aria-label="Permalink to &quot;GET `/inventory/stock/movements`&quot;">​</a></h3><p>Requires <code>product_id</code>; optional <code>warehouse_id</code>, pagination controls. Returns newest movements first.</p><h3 id="post-inventory-stock-adjust" tabindex="-1">POST <code>/inventory/stock/adjust</code> <a class="header-anchor" href="#post-inventory-stock-adjust" aria-label="Permalink to &quot;POST `/inventory/stock/adjust`&quot;">​</a></h3><p>Requires <code>inventory.adjust</code>.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;product_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;warehouse_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;in&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;quantity&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;notes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Initial count&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>type</code> is <code>in</code>, <code>out</code>, or <code>adjust</code>; the last sets the on-hand quantity. The product must track stock; stock cannot become negative. Omitting <code>warehouse_id</code> uses the default warehouse.</p><h2 id="transfers" tabindex="-1">Transfers <a class="header-anchor" href="#transfers" aria-label="Permalink to &quot;Transfers&quot;">​</a></h2><h3 id="get-inventory-transfers" tabindex="-1">GET <code>/inventory/transfers</code> <a class="header-anchor" href="#get-inventory-transfers" aria-label="Permalink to &quot;GET `/inventory/transfers`&quot;">​</a></h3><p>Query: <code>status</code> (<code>draft|in_transit|completed|cancelled</code>), <code>warehouse_id</code>, <code>search</code>, <code>trashed</code>, <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><h3 id="post-inventory-transfers" tabindex="-1">POST <code>/inventory/transfers</code> <a class="header-anchor" href="#post-inventory-transfers" aria-label="Permalink to &quot;POST `/inventory/transfers`&quot;">​</a></h3><p>Requires <code>inventory.transfer</code>.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;from_warehouse_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;to_warehouse_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;notes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Rebalance&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;lines&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;product_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;quantity&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Warehouses must differ. Creates a Draft transfer (<code>TRF-</code> number).</p><h3 id="get-put-delete-inventory-transfers-transfer" tabindex="-1">GET/PUT/DELETE <code>/inventory/transfers/{transfer}</code> <a class="header-anchor" href="#get-put-delete-inventory-transfers-transfer" aria-label="Permalink to &quot;GET/PUT/DELETE `/inventory/transfers/{transfer}`&quot;">​</a></h3><p>View, update, or soft-delete a transfer. Only Draft transfers can be updated or deleted. Update/creation requires <code>inventory.transfer</code>; delete requires <code>inventory.delete</code>.</p><h3 id="post-inventory-transfers-transfer-dispatch" tabindex="-1">POST <code>/inventory/transfers/{transfer}/dispatch</code> <a class="header-anchor" href="#post-inventory-transfers-transfer-dispatch" aria-label="Permalink to &quot;POST `/inventory/transfers/{transfer}/dispatch`&quot;">​</a></h3><p>Requires <code>inventory.transfer</code>; transitions <code>draft → in_transit</code>.</p><h3 id="post-inventory-transfers-transfer-complete" tabindex="-1">POST <code>/inventory/transfers/{transfer}/complete</code> <a class="header-anchor" href="#post-inventory-transfers-transfer-complete" aria-label="Permalink to &quot;POST `/inventory/transfers/{transfer}/complete`&quot;">​</a></h3><p>Requires <code>inventory.transfer</code>; transitions <code>in_transit → completed</code>, posting paired <code>transfer_out</code> and <code>transfer_in</code> movements.</p><h3 id="post-inventory-transfers-transfer-cancel" tabindex="-1">POST <code>/inventory/transfers/{transfer}/cancel</code> <a class="header-anchor" href="#post-inventory-transfers-transfer-cancel" aria-label="Permalink to &quot;POST `/inventory/transfers/{transfer}/cancel`&quot;">​</a></h3><p>Requires <code>inventory.transfer</code>; transitions Draft or In transit to Cancelled without posting stock.</p><h3 id="post-inventory-transfers-transfer-restore" tabindex="-1">POST <code>/inventory/transfers/{transfer}/restore</code> <a class="header-anchor" href="#post-inventory-transfers-transfer-restore" aria-label="Permalink to &quot;POST `/inventory/transfers/{transfer}/restore`&quot;">​</a></h3><p>Requires <code>inventory.restore</code>.</p><h3 id="delete-inventory-transfers-transfer-force" tabindex="-1">DELETE <code>/inventory/transfers/{transfer}/force</code> <a class="header-anchor" href="#delete-inventory-transfers-transfer-force" aria-label="Permalink to &quot;DELETE `/inventory/transfers/{transfer}/force`&quot;">​</a></h3><p>Requires <code>inventory.force.delete</code>; permanently deletes a soft-deleted transfer.</p>',32)])])}const y=t(i,[["render",o]]);export{k as __pageData,y as default};
